const D = { scale:1, n:16, jam:.6, density:.6, energy:.55, speed:1, headlight:.7, hue:210, x:.5, y:.55, style:'iso', act:'commute', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU2 = Math.PI * 2;
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const u = Math.min(width, height);
const N = Math.max(3, Math.min(30, Math.round(P.n)));
const ho = P.hue - 210;

const STY = {
  iso:       { mode:'iso',  road:[220,14,22], lane:[210,10,34], addLight:true },
  blueprint: { mode:'wire', road:[214,60,10], lane:[200,70,20], addLight:false },
  neon:      { mode:'neon', road:[260,40,8],  lane:[280,50,14], addLight:true },
  noir:      { mode:'noir', road:[220,6,10],  lane:[220,5,18],  addLight:true },
  pixel:     { mode:'pixel',road:[210,18,20], lane:[205,14,30], addLight:true } };
const st = STY[P.style] || STY.iso;

// iso basis (along-road + perpendicular depth), resolution-agnostic
const roadLen = width * 1.35;
const startX = -width * 0.175, startY = height * (P.y);
const alongX = roadLen, alongY = -height * 0.16;   // per s in 0..1
const perpX = u * 0.42, perpY = u * 0.30;          // per lane unit
const laneGap = 0.42;                               // lane separation in perp units
const vsX = u * 0.006 * P.scale, vsY = u * 0.006 * P.scale; // vehicle unit scale

// ---- road plane (cached parallelogram buffer) ----
const rKey = width + 'x' + height + P.style + Math.round(P.hue) + P.seed;
if (!S.bg || S.bgKey !== rKey) {
  if (!S.bg) S.bg = createGraphics(width, height);
  else S.bg.resizeCanvas(width, height);
  const g = S.bg;
  g.colorMode(g.HSB, 360, 100, 100, 100);
  g.clear();
  g.noStroke();
  const road = st.road, lane = st.lane;
  const halfW = 1.05;
  const pp = (s, lat) => [startX + alongX * s + perpX * lat, startY + alongY * s + perpY * lat];
  g.fill(hw(road[0] + ho), road[1], road[2], st.mode === 'neon' || st.mode === 'noir' ? 92 : 100);
  const a1 = pp(-0.05, -halfW), a2 = pp(1.05, -halfW), a3 = pp(1.05, halfW), a4 = pp(-0.05, halfW);
  g.quad(a1[0], a1[1], a2[0], a2[1], a3[0], a3[1], a4[0], a4[1]);
  g.fill(hw(lane[0] + ho), lane[1], lane[2], 90);
  const d1 = pp(-0.05, -0.03), d2 = pp(1.05, -0.03), d3 = pp(1.05, 0.03), d4 = pp(-0.05, 0.03);
  g.quad(d1[0], d1[1], d2[0], d2[1], d3[0], d3[1], d4[0], d4[1]);
  g.fill(hw(lane[0] + ho), 8, st.mode === 'blueprint' ? 60 : 82, 70);
  for (let k = 0; k < 26; k++) {
    const s0 = k / 26, s1 = s0 + 0.018;
    const m1 = pp(s0, -laneGap), m2 = pp(s1, -laneGap), m3 = pp(s1, -laneGap + 0.02), m4 = pp(s0, -laneGap + 0.02);
    g.quad(m1[0], m1[1], m2[0], m2[1], m3[0], m3[1], m4[0], m4[1]);
    const n1 = pp(s0, laneGap), n2 = pp(s1, laneGap), n3 = pp(s1, laneGap + 0.02), n4 = pp(s0, laneGap + 0.02);
    g.quad(n1[0], n1[1], n2[0], n2[1], n3[0], n3[1], n4[0], n4[1]);
  }
  S.bgKey = rKey;
}
image(S.bg, 0, 0);

// ---- vehicle fleet init ----
if (!S.v || S.vn !== N || S.vseed !== P.seed) {
  S.v = [];
  for (let i = 0; i < N; i++) {
    const r = fr(i * 5 + 3);
    const type = r < 0.16 ? 'bus' : (r < 0.42 ? 'scooter' : 'car');
    S.v.push({
      s0: fr(i * 5 + 1),
      dir: (i % 2 === 0) ? 1 : -1,
      lane: (i % 2 === 0) ? -laneGap : laneGap,
      type,
      spd: type === 'scooter' ? 0.09 : (type === 'bus' ? 0.045 : 0.065),
      len: type === 'bus' ? 3.4 : (type === 'scooter' ? 1.0 : 1.9),
      wid: type === 'bus' ? 1.1 : (type === 'scooter' ? 0.5 : 0.95),
      hgt: type === 'bus' ? 1.9 : (type === 'scooter' ? 0.9 : 1.0),
      hue: hw((r * 300 + i * 47) + ho) });
  }
  S.vn = N; S.vseed = P.seed;
}

const sec = ((Math.floor(K.section) % 8) + 8) % 8;
const ACT = {
  commute: [0.2, 0.5, 0.9, 0.4, 0.7, 1.0, 0.35, 0.6],
  gridlock:[0.7, 0.9, 1.0, 0.85, 1.0, 0.95, 0.8, 1.0],
  freeflow:[0.0, 0.15, 0.4, 0.1, 0.3, 0.5, 0.05, 0.25] };
const jamCurve = (ACT[P.act] || ACT.commute)[sec];
const jam = Math.min(1.4, P.jam * (0.4 + 1.2 * jamCurve));
const flow = (0.35 + 0.9 * P.energy) * P.speed * (1.05 - 0.55 * jam);
const nightF = (1 - K.intensity) * 0.7 + 0.3 + A.bass * 0.4;

const proj = (s, lat, lift) => [startX + alongX * s + perpX * lat, startY + alongY * s + perpY * lat - lift];
const nlen = Math.hypot(alongX, alongY);
const uax = alongX / nlen, uay = alongY / nlen;
const plen = Math.hypot(perpX, perpY);
const upx = perpX / plen, upy = perpY / plen;

const order = [];
for (let i = 0; i < N; i++) {
  const v = S.v[i];
  let s = v.s0 + K.t * v.spd * flow * v.dir;
  s = ((s % 1) + 1) % 1;
  const warp = jam * 0.06 * Math.sin(s * TAU2 * 3 - K.t * 0.5 * v.dir);
  let sd = s + warp;
  sd = ((sd % 1) + 1) % 1;
  const base = proj(sd, v.lane, 0);
  order.push({ v, sd, sy: base[1] });
}
order.sort((a, b) => a.sy - b.sy);

const drawBox = (cx, cy, len, wid, hgt, dir, col) => {
  const L2 = len * vsX * 3.2, W2 = wid * vsX * 3.2, H = hgt * vsY * 5.0;
  const axx = uax * L2, axy = uay * L2;
  const pxx = upx * W2, pyy = upy * W2;
  const fdir = dir >= 0 ? 1 : -1;
  const fx = cx + axx * fdir, fy = cy + axy * fdir;
  const bx = cx - axx * fdir, by = cy - axy * fdir;
  const fl = [fx - pxx, fy - pyy], frr = [fx + pxx, fy + pyy];
  const bl = [bx - pxx, by - pyy], brr = [bx + pxx, by + pyy];
  const up = [0, -H];
  const shade = st.mode;
  const t = pt => [pt[0] + up[0], pt[1] + up[1]];
  const tfl = t(fl), tfr = t(frr), tbl = t(bl), tbr = t(brr);
  if (shade === 'wire') {
    stroke(hw(col + ho), 70, 96, 90); strokeWeight(1.1); noFill();
    quad(fl[0], fl[1], frr[0], frr[1], brr[0], brr[1], bl[0], bl[1]);
    quad(tfl[0], tfl[1], tfr[0], tfr[1], tbr[0], tbr[1], tbl[0], tbl[1]);
    line(fl[0], fl[1], tfl[0], tfl[1]); line(frr[0], frr[1], tfr[0], tfr[1]);
    line(bl[0], bl[1], tbl[0], tbl[1]); line(brr[0], brr[1], tbr[0], tbr[1]);
    noStroke();
    return [fx, fy, fdir];
  }
  let hb, sb, top, rgt, lft, ea;
  if (shade === 'neon') { hb = hw(col + ho); sb = 80; top = 22; rgt = 16; lft = 12; ea = 92; }
  else if (shade === 'noir') { hb = hw(col + ho); sb = 8; top = 26; rgt = 15; lft = 8; ea = 0; }
  else if (shade === 'pixel') { const q = 30; hb = hw(Math.round(col / q) * q + ho); sb = 55; top = 62; rgt = 44; lft = 32; ea = 0; }
  else { hb = hw(col + ho); sb = 46; top = 74; rgt = 52; lft = 38; ea = 0; }
  noStroke();
  fill(hb, sb, lft); quad(bl[0], bl[1], fl[0], fl[1], tfl[0], tfl[1], tbl[0], tbl[1]);
  fill(hb, sb, rgt); quad(fl[0], fl[1], frr[0], frr[1], tfr[0], tfr[1], tfl[0], tfl[1]);
  fill(hb, sb, rgt * 0.9); quad(frr[0], frr[1], brr[0], brr[1], tbr[0], tbr[1], tfr[0], tfr[1]);
  fill(hb, sb * 0.8, top); quad(tfl[0], tfl[1], tfr[0], tfr[1], tbr[0], tbr[1], tbl[0], tbl[1]);
  if (ea > 0) {
    stroke(hb, 30, 100, ea); strokeWeight(1);
    line(tfl[0], tfl[1], tfr[0], tfr[1]); line(tfr[0], tfr[1], tbr[0], tbr[1]);
    line(tbr[0], tbr[1], tbl[0], tbl[1]); line(tbl[0], tbl[1], tfl[0], tfl[1]);
    noStroke();
  }
  return [fx, fy, fdir];
};

for (let q = 0; q < order.length; q++) {
  const v = order[q].v, sd = order[q].sd;
  const base = proj(sd, v.lane, 0);
  const front = drawBox(base[0], base[1], v.len, v.wid, v.hgt, v.dir, v.hue);
  if (st.addLight && st.mode !== 'wire' && front) {
    const fx = front[0], fy = front[1], fdir = front[2];
    push();
    blendMode(ADD);
    noStroke();
    const hi = (st.mode === 'neon' ? 0.9 : 0.6) * P.headlight * nightF;
    const gx = fx + uax * fdir * u * 0.02, gy = fy + uay * fdir * u * 0.02;
    fill(48, 30, 100, 34 * hi);
    ellipse(gx, gy, u * 0.05 * P.scale, u * 0.035 * P.scale);
    fill(52, 20, 100, 60 * hi);
    ellipse(gx, gy, u * 0.02 * P.scale, u * 0.016 * P.scale);
    const rx = fx - uax * fdir * v.len * vsX * 6, ry = fy - uay * fdir * v.len * vsX * 6;
    fill(hw(2 + ho), 85, 100, 26 * hi);
    ellipse(rx, ry, u * 0.02 * P.scale, u * 0.016 * P.scale);
    blendMode(BLEND);
    pop();
  }
}

if (st.mode === 'neon') {
  push();
  blendMode(ADD);
  noStroke();
  const sw = (K.t * 0.07) % 1;
  const sp = proj(sw, 0, 0);
  fill(hw(300 + ho), 60, 100, 8);
  ellipse(sp[0], sp[1], u * 0.5, u * 0.16);
  blendMode(BLEND);
  pop();
}
blendMode(BLEND);
